#include <cstdlib>
#include <iostream>

struct Point {
    int x;
    int y;
};

int main() {
    Point a{0, 0};
    Point b{0, 0};
    std::cin >> a.x >> a.y >> b.x >> b.y;
    int distance = std::abs(a.x - b.x) + std::abs(a.y - b.y);
    std::cout << distance << std::endl;
    return 0;
}
